// Bookshelf page. Book data comes from assets/js/books-data.js
// (generated by tools/build_books.py from a Goodreads export).
(() => {
  const BOOKS = window.BOOKS || [];
  const root = document.documentElement;
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  const esc = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const readOn = (d) => (d ? `${MONTHS[+d.slice(5, 7) - 1]} ${d.slice(0, 4)}` : null);
  // A fractional rating (3.5) lights that much of the next bolt: the lit copy is
  // clipped where the bolt's own width (x 4.5 to 18.5 of 24) reaches the fraction.
  const bolt = (on) => `<svg class="${on ? "is-on" : ""}" aria-hidden="true"><use href="#bolt" /></svg>`;
  const bolts = (n) =>
    `<span class="bolts" role="img" aria-label="Rated ${n} out of 5">${[1, 2, 3, 4, 5]
      .map((i) => {
        const f = Math.min(1, Math.max(0, n - i + 1));
        if (f === 0 || f === 1) return bolt(f === 1);
        const cut = (100 - ((4.5 + 14 * f) / 24) * 100).toFixed(1);
        return `<span class="bolt-part" style="--cut:${cut}%" aria-hidden="true">${bolt(false)}${bolt(true)}</span>`;
      })
      .join("")}</span>`;
  // Filtering and sorting go by whole bolts: a 3.5 sits with the 3s
  const tier = (b) => Math.floor(b.rating);

  // Deterministic accent for books without a cover image
  const hue = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) % 360, 7);
  const fallbackCover = (b) => `
    <div class="cover-fallback" style="--h:${hue(b.title)}">
      <svg aria-hidden="true"><use href="#bolt" /></svg>
      <strong>${esc(b.title)}</strong>
      <small>${esc(b.author)}</small>
    </div>`;

  // ---------- stats ----------
  const pages = BOOKS.reduce((n, b) => n + (b.pages || 0), 0);
  const avg = BOOKS.length ? BOOKS.reduce((n, b) => n + b.rating, 0) / BOOKS.length : 0;
  const fives = BOOKS.filter((b) => b.rating === 5).length;
  document.getElementById("shelf-stats").innerHTML =
    `<strong>${BOOKS.length}</strong> books and <strong>${pages.toLocaleString()}</strong> pages so far, averaging ` +
    `<strong>${avg.toFixed(1)}</strong> bolts. The <strong>${fives}</strong> five-bolt ${fives === 1 ? "read is the one" : "reads are the ones"} I'd push on anyone.`;

  // ---------- currently reading: from the Goodreads "currently-reading" shelf ----------
  const NOW = window.CURRENTLY_READING || [];
  const nowEl = document.getElementById("now-reading");
  if (NOW.length) {
    nowEl.hidden = false;
    nowEl.innerHTML = NOW.map((b) => {
      const meta = ['<span class="now-book__label"><span class="live-dot" aria-hidden="true"></span>Currently reading</span>', esc(b.author), b.year, b.pages ? `${b.pages} pages` : null]
        .filter(Boolean).join(" · ");
      const series = b.series ? `<p class="book__series">${esc(b.series)}${b.seriesNo ? ` · Book ${esc(b.seriesNo)}` : ""}</p>` : "";
      return `
        <article class="now-book">
          <div class="now-book__cover">
            <div class="book3d">
              ${b.cover ? `<img src="${b.cover}" alt="Cover of ${esc(b.title)}" width="180" height="270" />` : fallbackCover(b)}
            </div>
            <span class="now-book__ribbon" aria-hidden="true"></span>
          </div>
          <div class="now-book__body">
            <h2 class="now-book__title">${esc(b.title)}</h2>
            ${series}
            <p class="book__meta">${meta}</p>
            <div class="now-book__verdict">
              <span class="bolts bolts--charging" role="img" aria-label="Not rated yet">${[0, 1, 2, 3, 4]
                .map((i) => `<svg style="--i:${i}" aria-hidden="true"><use href="#bolt" /></svg>`)
                .join("")}</span>
              <span>Verdict pending: review once I've finished</span>
            </div>
            <a class="book__gr" href="${b.goodreads}" target="_blank" rel="noopener">Goodreads <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M9 7h8v8" /></svg></a>
          </div>
        </article>`;
    }).join("");
  }

  // ---------- the shelf: one spine per book, height scaled by page count ----------
  // (cover URLs are made absolute: a url() inside a CSS variable resolves against the stylesheet's folder)
  const pageCounts = BOOKS.map((b) => b.pages || 300);
  const minP = Math.min(...pageCounts), maxP = Math.max(...pageCounts);
  const spineHeight = (p) => Math.round(118 + ((p - minP) / Math.max(1, maxP - minP)) * 72); // 118–190px
  document.getElementById("shelf-row").innerHTML = BOOKS.map(
    (b) => `
    <button class="spine" type="button" data-book="${b.id}" style="--sh:${spineHeight(b.pages || 300)}px;--h:${hue(b.title)}${b.cover ? `;--img:url('${new URL(b.cover, location.href).href}')` : ""}"
      aria-label="${esc(b.title)}, ${b.rating} bolts, jump to review">
      <span class="spine__title">${esc(b.title)}</span>
      <span class="spine__tip" aria-hidden="true">${esc(b.title)} · ${b.rating}/5</span>
    </button>`
  ).join("");

  // ---------- filters + sorting ----------
  const filter = document.getElementById("rating-filter");
  const sortBy = document.getElementById("sort-by");
  let minRating = 0;
  const counts = (r) => BOOKS.filter((b) => tier(b) === r).length;
  filter.innerHTML =
    `<button type="button" class="chip is-on" data-rating="0" aria-pressed="true">All <span>${BOOKS.length}</span></button>` +
    [5, 4, 3, 2, 1]
      .filter((r) => counts(r))
      .map((r) => `<button type="button" class="chip" data-rating="${r}" aria-pressed="false">${bolts(r)}<span>${counts(r)}</span></button>`)
      .join("");

  const sorters = {
    recent: (a, b) => (b.dateRead || "").localeCompare(a.dateRead || "") || a.title.localeCompare(b.title),
    rating: (a, b) => tier(b) - tier(a) || (b.dateRead || "").localeCompare(a.dateRead || ""),
    pages: (a, b) => (b.pages || 0) - (a.pages || 0),
    title: (a, b) => a.title.replace(/^The /, "").localeCompare(b.title.replace(/^The /, "")),
  };

  const list = document.getElementById("book-list");
  function card(b) {
    const series = b.series ? `${esc(b.series)}${b.seriesNo ? ` · Book ${esc(b.seriesNo)}` : ""}` : "";
    const meta = [esc(b.author), b.year, b.pages ? `${b.pages} pages` : null].filter(Boolean).join(" · ");
    const read = readOn(b.dateRead);
    return `
      <article class="book reveal" id="book-${b.id}">
        <div class="book__cover">
          <div class="book3d">
            ${b.cover ? `<img src="${b.cover}" alt="Cover of ${esc(b.title)}" loading="lazy" width="180" height="270" />` : fallbackCover(b)}
          </div>
        </div>
        <div class="book__body">
          <h2 class="book__title">${esc(b.title)}</h2>
          ${series ? `<p class="book__series">${series}</p>` : ""}
          <p class="book__meta">${meta}</p>
          <div class="book__rating">${bolts(b.rating)}${read ? `<span class="book__read">Read ${read}</span>` : ""}</div>
          <blockquote class="book__review"><p>${esc(b.review)}</p></blockquote>
          <div class="book__actions">
            <button class="book__more" type="button" hidden aria-expanded="false">Read full review</button>
            <a class="book__gr" href="${b.goodreads}" target="_blank" rel="noopener">Goodreads <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M9 7h8v8" /></svg></a>
          </div>
        </div>
      </article>`;
  }

  function render() {
    const shown = BOOKS.filter((b) => !minRating || tier(b) === minRating).sort(sorters[sortBy.value]);
    list.innerHTML = shown.map(card).join("");
    // Swap broken cover images for the generated cover
    list.querySelectorAll(".book3d img").forEach((img) =>
      img.addEventListener("error", () => {
        const b = BOOKS.find((x) => `book-${x.id}` === img.closest(".book").id);
        img.outerHTML = fallbackCover(b);
      }, { once: true })
    );
    // Only offer "Read full review" when the review is actually clamped
    requestAnimationFrame(() =>
      list.querySelectorAll(".book").forEach((el) => {
        const r = el.querySelector(".book__review p"); // the clamped element
        el.querySelector(".book__more").hidden = r.scrollHeight <= r.clientHeight + 2;
      })
    );
    observeReveals();
  }

  filter.addEventListener("click", (e) => {
    const chip = e.target.closest(".chip");
    if (!chip) return;
    minRating = +chip.dataset.rating;
    filter.querySelectorAll(".chip").forEach((c) => {
      c.classList.toggle("is-on", c === chip);
      c.setAttribute("aria-pressed", String(c === chip));
    });
    render();
  });
  sortBy.addEventListener("change", render);

  list.addEventListener("click", (e) => {
    const more = e.target.closest(".book__more");
    if (!more) return;
    const book = more.closest(".book");
    const open = book.classList.toggle("is-expanded");
    more.setAttribute("aria-expanded", String(open));
    more.textContent = open ? "Show less" : "Read full review";
  });

  // Spine click: jump to (and flash) that book's review, clearing filters if needed
  document.getElementById("shelf-row").addEventListener("click", (e) => {
    const spine = e.target.closest(".spine");
    if (!spine) return;
    if (minRating && !BOOKS.some((b) => b.id === spine.dataset.book && tier(b) === minRating)) {
      filter.querySelector('[data-rating="0"]').click();
    }
    const el = document.getElementById(`book-${spine.dataset.book}`);
    el.classList.add("is-in");
    el.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "center" });
    el.classList.remove("is-flash");
    el.offsetWidth;
    el.classList.add("is-flash");
  });

  // ---------- shared chrome: theme, nav, reveals ----------
  document.getElementById("theme-toggle").addEventListener("click", () => {
    const next = root.dataset.theme === "dark" ? "light" : "dark";
    root.dataset.theme = next;
    try { localStorage.setItem("theme", next); } catch (e) {}
    document.querySelectorAll('meta[name="theme-color"]').forEach((m) => (m.content = next === "light" ? "#fafaf9" : "#0a0a0b"));
  });
  const nav = document.querySelector(".nav");
  const onScroll = () => nav.classList.toggle("is-scrolled", scrollY > 8);
  onScroll();
  addEventListener("scroll", onScroll, { passive: true });
  const menuBtn = document.getElementById("menu-toggle");
  const navLinks = document.getElementById("nav-links");
  menuBtn.addEventListener("click", () => {
    const open = navLinks.classList.toggle("is-open");
    menuBtn.setAttribute("aria-expanded", String(open));
  });

  const revealer = new IntersectionObserver(
    (entries) => entries.forEach((en) => en.isIntersecting && (en.target.classList.add("is-in"), revealer.unobserve(en.target))),
    { rootMargin: "0px 0px -6% 0px" }
  );
  function observeReveals() {
    // what is already on screen shows at once; only cards below the fold wait for the observer
    document.querySelectorAll(".reveal:not(.is-in)").forEach((el, i) => {
      if (el.closest(".shelf-hero") || el.getBoundingClientRect().top < innerHeight) return el.classList.add("is-in");
      el.style.transitionDelay = `${Math.min(i % 4, 3) * 50}ms`;
      revealer.observe(el);
    });
    root.classList.add("reveal-on");
  }

  document.getElementById("year").textContent = new Date().getFullYear();
  render();
})();
